changeSet.sql:
ALTER TABLE ai_llm_call_recommendations
    ADD COLUMN IF NOT EXISTS previous_recommendation_id INTEGER
        REFERENCES ai_llm_call_recommendations(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS model_set_by_owner BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE ai_workflow_analyses
    DROP CONSTRAINT IF EXISTS ai_workflow_analyses_status_check;
ALTER TABLE ai_workflow_analyses
    ADD CONSTRAINT ai_workflow_analyses_status_check
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'skipped'));

rollback.sql:
DELETE FROM ai_workflow_analyses WHERE status = 'skipped';
ALTER TABLE ai_workflow_analyses
    DROP CONSTRAINT IF EXISTS ai_workflow_analyses_status_check;
ALTER TABLE ai_workflow_analyses
    ADD CONSTRAINT ai_workflow_analyses_status_check
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed'));
ALTER TABLE ai_llm_call_recommendations
    DROP COLUMN IF EXISTS model_set_by_owner,
    DROP COLUMN IF EXISTS previous_recommendation_id;
